<?php
require __DIR__.'/includes/module.php';$u=require_auth();require_permission('tasks.view');module_action('tasks');$bid=(int)$u['business_id'];$pdo=db();if($_SERVER['REQUEST_METHOD']==='POST')redirect('tasks.php');$q=$pdo->prepare('SELECT t.*,c.name customer FROM tasks t LEFT JOIN customers c ON c.id=t.customer_id WHERE t.business_id=? ORDER BY t.status="Completed",t.due_date IS NULL,t.due_date');$q->execute([$bid]);$rows=$q->fetchAll();$c=$pdo->prepare('SELECT id,name FROM customers WHERE business_id=? AND archived_at IS NULL ORDER BY name');$c->execute([$bid]);$customers=$c->fetchAll();$fields='<label class="wide">Task title *<input required name="title"></label><label>Customer<select name="customer_id"><option value="">No linked customer</option>';foreach($customers as $cu)$fields.='<option value="'.(int)$cu['id'].'">'.e($cu['name']).'</option>';$fields.='</select></label><label>Priority<select name="priority"><option>Medium</option><option>High</option><option>Low</option></select></label><label>Due date<input type="date" name="due_date"></label><label>Description<input name="description"></label>';page_start('Tasks & reminders','tasks');module_css('tasks');?><div class="section-head"><div><span class="eyebrow">YOUR WORKFLOW</span><h1>Tasks & reminders</h1><p>Turn good intentions into the next clear step.</p></div><button class="button primary" onclick="document.getElementById('record-modal').showModal()"><i class="ti ti-plus"></i> Add task</button></div><div class="content-card"><div class="table-scroll"><table class="data-table"><thead><tr><th>TASK</th><th>CUSTOMER</th><th>PRIORITY</th><th>DUE DATE</th><th>STATUS</th><th></th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td class="table-strong"><?=e($r['title'])?></td><td><?=e($r['customer']?:'—')?></td><td><span class="pill"><?=e($r['priority'])?></span></td><td><?=fmt_date($r['due_date'])?></td><td><?=e($r['status'])?></td><td><?php if($r['status']!=='Completed'):?><form method="post"><input type="hidden" name="_csrf" value="<?=e(csrf())?>"><input type="hidden" name="action" value="complete"><input type="hidden" name="id" value="<?=(int)$r['id']?>"><button class="link-button">Complete</button></form><?php endif?></td></tr><?php endforeach;if(!$rows):?><tr><td colspan="6" class="empty-row">Nothing on your list yet. Add a task to get started.</td></tr><?php endif?></tbody></table></div></div><?php modal_form('Add task','create',$fields);page_end();
